template <typename T, size_t N, size_t... I>
constexpr std::array<T, N> reverse_array_impl(
    const std::array<T, N>& arr, std::index_sequence<I...>)
{
    // Modifies element order via index pack expansion
    return { arr[N - 1 - I]... };
}

template <typename T, size_t N>
constexpr std::array<T, N> reverse_array(const std::array<T, N>& arr)
{
    return reverse_array_impl(arr, std::make_index_sequence<N>{});
}

constexpr std::array<int, 3> initial = {10, 20, 30};
constexpr auto reversed = reverse_array(initial); // {30, 20, 10}

// Use case: Creating an array whose elements are derived from indices
template <size_t... I>
constexpr auto make_squares(std::index_sequence<I...>)
{
    return std::array<size_t, sizeof...(I)>{ (I * I)... };
}
constexpr auto squares = make_squares(std::make_index_sequence<5>{});
// squares is {0, 1, 4, 9, 16}
